(13, 'profil.tentang-kami', 'about.hero.title', 'Judul Tentang Kami', 'Tentang LPPM IBI KKG', 'text', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(14, 'profil.tentang-kami', 'about.hero.desc', 'Deskripsi Singkat Tentang Kami', 'Lembaga Penelitian dan Pengabdian kepada Masyarakat (LPPM) merupakan unit strategis yang mengelola, mengembangkan, dan mendukung penuh pelaksanaan riset ilmiah, pengabdian masyarakat, publikasi ilmiah, serta penguatan jejaring kerja sama tridharma.', 'textarea', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(15, 'profil.tentang-kami', 'about.short_profile.title', 'Judul Profil Singkat', 'Profil Singkat', 'text', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(16, 'profil.tentang-kami', 'about.short_profile.text1', 'Paragraf Profil Singkat 1', 'LPPM IBI KKG bertugas mengelola proses administratif, akademik, dan strategis dalam pelaksanaan penelitian dosen, pengabdian kepada masyarakat, publikasi ilmiah, serta pengembangan kolaborasi dengan mitra internal maupun eksternal.', 'textarea', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(17, 'profil.tentang-kami', 'about.short_profile.text2', 'Paragraf Profil Singkat 2', 'Melalui pengelolaan yang profesional, transparan, dan berbasis teknologi informasi, LPPM berkomitmen memfasilitasi sivitas akademika guna melahirkan karya riset inovatif dan program pengabdian yang memberikan kontribusi nyata bagi masyarakat luas.', 'textarea', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(18, 'profil.tentang-kami', 'about.tasks.text', 'Tugas Utama (Satu baris per Tugas, tekan Enter)', 'Mengelola administrasi dan pendanaan internal/eksternal penelitian dosen.
Mengoordinasikan dan merancang agenda pengabdian kepada masyarakat (Abdimas).
Mendorong luaran ilmiah bermutu tinggi melalui pembinaan berkelanjutan.
Menyediakan standarisasi panduan, dokumen administrasi, serta template resmi.
Membangun kerja sama strategis multi-sektoral dengan industri, pemerintah, dan LSM.', 'textarea', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(19, 'profil.tentang-kami', 'about.functions.text', 'Fungsi Strategis (Satu baris per Fungsi, tekan Enter)', 'Sebagai katalisator utama pengembangan iklim riset institusi.
Sebagai jembatan hilirisasi karya keilmuan dosen ke masyarakat.
Sebagai fasilitator peningkatan sitasi dan indeks publikasi ilmiah global.
Sebagai penyedia platform terintegrasi untuk seluruh layanan tridharma.', 'textarea', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(20, 'profil.tentang-kami', 'about.pillar.penelitian', 'Ruang Lingkup: Deskripsi Penelitian', 'Mengelola pengajuan proposal hibah, proses monitoring evaluasi berkala, pelaporan keuangan, hingga pendampingan paten dan HKI hasil riset dosen.', 'textarea', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(21, 'profil.tentang-kami', 'about.pillar.abdimas', 'Ruang Lingkup: Deskripsi Abdimas', 'Menyelenggarakan kegiatan pengabdian masyarakat berorientasi dampak, memandu program binaan desa mitra, serta mengoordinasikan laporan pengabdian.', 'textarea', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(22, 'profil.tentang-kami', 'about.pillar.publikasi', 'Ruang Lingkup: Deskripsi Publikasi & Jurnal', 'Dukungan penyuntingan artikel ilmiah, penyediaan direktori jurnal bereputasi nasional dan internasional, serta pengurusan insentif publikasi.', 'textarea', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(23, 'profil.tentang-kami', 'about.values.tertib', 'Core Value: Deskripsi Tertib', 'Tata kelola administrasi yang rapi, transparan, terdokumentasi, dan sesuai dengan standar nasional DIKTI.', 'textarea', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(24, 'profil.tentang-kami', 'about.values.transparan', 'Core Value: Deskripsi Transparan', 'Keterbukaan informasi terkait skema dana hibah riset, penilaian proposal, hasil monev, hingga pembagian insentif.', 'textarea', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(25, 'profil.tentang-kami', 'about.values.adaptif', 'Core Value: Deskripsi Adaptif', 'Terus berinovasi dan menyesuaikan layanan dengan kebutuhan digitalisasi tridharma perguruan tinggi.', 'textarea', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(26, 'profil.tentang-kami', 'about.values.berkualitas', 'Core Value: Deskripsi Berkualitas', 'Memprioritaskan mutu hasil luaran yang berdaya saing nasional serta berorientasi dampak global.', 'textarea', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(27, 'profil.tentang-kami', 'about.commitment.title', 'Judul Komitmen Kami', 'Pemberdayaan Berkelanjutan & Dampak Nyata', 'text', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(28, 'profil.tentang-kami', 'about.commitment.text', 'Paragraf Komitmen Kami', 'LPPM IBI KKG berkomitmen untuk secara konsisten memberikan pelayanan prima yang adaptif dan berorientasi kualitas. Melalui sinergi riset akademis dan program pengabdian inovatif, kami bertekad mempercepat pertumbuhan keilmuan civitas akademika dan mewujudkan kolaborasi bernilai tambah tinggi bagi masyarakat dan mitra strategis.', 'textarea', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(29, 'profil.visi-misi', 'visi_misi.hero.title', 'Judul Visi & Misi', 'Arah Strategis', 'text', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(30, 'profil.visi-misi', 'visi_misi.hero.desc', 'Deskripsi Hero Visi & Misi', 'Tujuan dan Sasaran Strategis Lembaga Penelitian dan Pengabdian kepada Masyarakat (LPPM) IBI Kwik Kian Gie.', 'textarea', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(31, 'profil.visi-misi', 'visi_misi.visi.text', 'Teks Visi LPPM', 'Menjadi lembaga pengelola tridharma yang unggul secara nasional, adaptif, dan berorientasi kualitas untuk menghasilkan riset inovatif dan pengabdian yang berdampak nyata bagi masyarakat luas pada tahun 2030.', 'textarea', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(32, 'profil.visi-misi', 'visi_misi.misi.text', 'Teks Misi LPPM (Gunakan Enter untuk pemisah)', 'Meningkatkan kuantitas dan kualitas penelitian dosen yang relevan dengan kebutuhan industri.
Menyelenggarakan pengabdian masyarakat berbasis produk inovasi dan tepat guna.
Mendorong luaran jurnal ilmiah terakreditasi nasional (SINTA) dan internasional bereputasi.', 'textarea', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(33, 'profil.struktur-organisasi', 'struktur.hero.title', 'Judul Struktur Organisasi', 'Struktur Organisasi', 'text', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(34, 'profil.struktur-organisasi', 'struktur.hero.desc', 'Deskripsi Hero Struktur', 'Susunan kepengurusan dan tata kelola organisasi Lembaga Penelitian dan Pengabdian kepada Masyarakat (LPPM) IBI Kwik Kian Gie.', 'textarea', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(35, 'profil.struktur-organisasi', 'struktur.pimpinan.ketua', 'Nama Ketua LPPM', 'Dr. Carmel Meiden, S.E., M.Si., Ak, CA, CSRA.', 'text', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(36, 'profil.struktur-organisasi', 'struktur.pimpinan.sekretaris', 'Nama Sekretaris LPPM', 'Amelia Sandra, S.E., Ak., M.Si., M.Ak.', 'text', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(37, 'profil.prestasi', 'prestasi.hero.title', 'Judul Halaman Prestasi', 'Prestasi & Penghargaan', 'text', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(38, 'profil.prestasi', 'prestasi.hero.desc', 'Deskripsi Halaman Prestasi', 'Catatan keunggulan akademik, hibah penelitian nasional, dan luaran bermutu tinggi dari sivitas akademika IBI Kwik Kian Gie.', 'textarea', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(39, 'akademisi', 'dosen.hero.title', 'Judul Menu Akademisi', 'Akademisi & Dosen Peneliti', 'text', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(40, 'akademisi', 'dosen.hero.desc', 'Deskripsi Menu Akademisi', 'Direktori dosen pengajar, kepangkatan akademik, serta fokus kepakaran tridharma penelitian di IBI Kwik Kian Gie.', 'textarea', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(41, 'penelitian', 'penelitian.hero.title', 'Judul Halaman Penelitian', 'Penelitian & Pengabdian LPPM', 'text', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
(42, 'penelitian', 'penelitian.hero.desc', 'Deskripsi Halaman Penelitian', 'Informasi skema pendanaan riset internal/nasional, pengumuman seleksi, dan panduan pengabdian masyarakat.', 'textarea', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
