(44, 'publikasi', 'publikasi.hero.desc', 'Deskripsi Halaman Publikasi', 'Akses jurnal resmi terakreditasi, artikel ilmiah, prosiding nasional, serta direktori indeksasi sitasi dosen.', 'textarea', '2026-09-15 06:46:56', '2026-09-15 06:46:56'),
